                 * (7541#5.2).
                 */
                if (bleft > 7)
                        return -1;

                if ((code & -(1 << (32 - bleft))) != (uint32_t)-(1 << (32 - bleft)))
                        return -1;
        }

        if (out < out_end)
                *out = 0; // end of string whenever possible
        return out - out_start;
